import {PERSPECTIVES,COLUMNS,FACETS,visibleFacets,facetOptions,valueLabel,label,values,buckets,cellText,targetText,missingText,matchingTargets,matchingDetails} from '../../integrations/javascript/evidence-model.mjs';
import {savedViews,storageNotice} from './report-state.js';
import {esc,list} from './evidence-reader.js';
export const selected=v=>Array.isArray(v)?v:v?[v]:[];
export const options=(items,value)=>items.map(([id,text])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(text)}</option>`).join('');
export const recordConditions=(r,filters={})=>[...new Set(matchingTargets(r,filters).filter(t=>t.conditionality==='explicitly_conditional'||t.condition_text).map(t=>t.condition_text||'Explicitly conditional target'))];
function filterSelect(p,v,key){return `<label>${esc(FACETS[key])}<select id="pf-${key}" data-filter="${key}"><option value="">All</option>${options(facetOptions(p,key).map(x=>[x.id,x.label]),selected(v.filters[key])[0])}${selected(v.filters[key]).length>1?'<option value="__multiple" selected>Multiple selected</option>':''}</select></label>`;}
export function toolbar(p,v){
 const names=savedViews(p),common=['domain',v.perspective==='risk'?'hazards':v.perspective==='targets'?'conditionality':v.perspective==='delivery'?'actor':'topic'];
 const active=Object.entries(v.filters).filter(([k,val])=>k==='query'?!!val:selected(val).length);
 return `<div class="perspective-bar" aria-label="Evidence perspective">${Object.entries(PERSPECTIVES).map(([id,title])=>`<button id="perspective-${id}" data-perspective="${id}" aria-pressed="${v.perspective===id}">${title}</button>`).join('')}<details class="customize"><summary>Customize view</summary><div class="customize-body"><button data-reset>Reset view</button><p class="muted">${esc(storageNotice())}</p><div class="filter-row"><label>Sort<select id="pv-sort" data-setting="sort">${options([['source','Source order'],['label','Statement A–Z'],['kind','Statement type'],['period','Stated period (text order)']],v.sort)}</select></label><label>Group<select id="pv-group" data-setting="group">${options([['none','No grouping'],['kind','Statement type'],['domain','Domain (overlapping)'],['source','Document (overlapping)']],v.group)}</select></label></div><fieldset><legend>Table columns</legend>${Object.entries(COLUMNS).map(([id,title])=>`<label class="check-choice"><input id="col-${id}" type="checkbox" data-column="${id}" ${v.columns.includes(id)?'checked':''} ${id==='statement'?'disabled':''}>${title}</label>`).join('')}</fieldset><fieldset><legend>Summary sections</legend>${[['visuals','Visual summaries'],['priorities','Priorities and their basis'],['questions','Follow-up questions']].map(([id,title])=>`<label class="check-choice"><input id="section-${id}" type="checkbox" data-section="${id}" ${v.sections[id]?'checked':''}>${title}</label>`).join('')}</fieldset><details><summary>All filters · choose multiple values</summary><p class="muted">Match any selected value within a field and all selected fields. Target condition and period match the same variant. Hazard/function co-occurrence does not establish a causal connection.</p><div class="facet-grid">${Object.keys(visibleFacets(p)).map(key=>`<fieldset><legend>${esc(FACETS[key])}</legend>${facetOptions(p,key).map(o=>`<label class="check-choice"><input type="checkbox" data-multi="${key}" value="${esc(o.id)}" ${selected(v.filters[key]).includes(o.id)?'checked':''}>${esc(o.label)}</label>`).join('')||'<span class="muted">No extracted values</span>'}</fieldset>`).join('')}</div><button data-apply-filters>Apply selected filters</button></details><div class="save-view"><label>View name<input id="view-name" maxlength="80" value="${esc(v.name)}" placeholder="For example: flood preparedness"></label><button data-save-view>Save named view</button><label>Saved on this browser<select id="saved-view"><option value="">Choose a saved view</option>${names.map((n,i)=>`<option value="${i}">${esc(n.name)}${n.view.profileId!==p.id?' · another version':''}</option>`).join('')}</select></label><button data-load-view>Apply saved view to this version</button></div></div></details></div>
 <div class="filter-row report-filters"><label class="search-label">Search evidence<input id="pf-query" data-filter="query" type="search" placeholder="Statement, institution, source or original text" value="${esc(v.filters.query||'')}"></label>${common.map(k=>filterSelect(p,v,k)).join('')}${Object.values(v.filters).some(x=>Array.isArray(x)?x.length:!!x)?'<button data-clear-all>Clear filters</button>':''}</div><div class="active-filters" aria-label="Active filters">${active.map(([k,val])=>`<button data-clear="${k}" aria-label="Remove ${esc(k==='query'?'search':FACETS[k])} filter">${esc(k==='query'?`Search: ${val}`:`${FACETS[k]}: ${selected(val).map(id=>valueLabel(p,k,id)).join(', ')}`)} ×</button>`).join('')}</div>`;
}
export function visualSummary(p,records,key){
 const groups=buckets(p,records,key),title=key==='domain'?'Evidence by domain':key==='hazards'?'Source-reported hazards':key==='risk_functions'?'Risk and resilience functions':'Disaster risk phases';
 return `<section class="visual-summary"><h3>${title}</h3><p class="muted">${records.length} filtered source records. Categories overlap; frequency is not importance or severity.</p><div class="bar-list">${groups.map(g=>`<button data-bucket="${key}" data-value="${esc(g.id)}" aria-label="Explore ${esc(g.label)}: ${g.recordIds.length} source records"><span>${esc(g.label)}</span><span class="bar-track" aria-hidden="true"><span style="width:${records.length?100*g.recordIds.length/records.length:0}%"></span></span><strong>${g.recordIds.length}</strong></button>`).join('')||'<p>No labels recorded for this dimension.</p>'}</div><details><summary>Table alternative and counting rule</summary><table class="data-table"><caption>Distinct source records per category; denominator ${records.length}</caption><thead><tr><th scope="col">Category</th><th scope="col">Source records</th></tr></thead><tbody>${groups.map(g=>`<tr><th scope="row">${esc(g.label)}</th><td>${g.recordIds.length}</td></tr>`).join('')}</tbody></table><p>Each record counts once per category and once overall. Missing labels are not assigned. Repeated source statements remain separate. Select a bar to inspect its records.</p></details></section>`;
}
export function recordTable(p,records,v){
 const renderRows=rows=>rows.map(r=>`<tr data-profile-row="${esc(r.local_id)}">${v.columns.map(c=>`<${c==='statement'?'th scope="row"':'td'}>${c==='statement'?`<button class="table-link statement-link" data-record="${esc(r.local_id)}">${esc(r.label_en)} →</button>${recordConditions(r,v.filters).map(c=>`<small class="qualification">${esc(c)}</small>`).join('')}${v.columns.includes("kind")?"":`<small>${esc(label(p,'record_kinds',r.kind))}</small>`}`:`<span class="cell-text">${esc(cellText(p,r,c,v.filters))}</span>`}</${c==='statement'?'th':'td'}>`).join('')}</tr>`).join('');
 const groups=v.group==='none'?[{label:'',recordIds:records.map(r=>r.local_id)}]:buckets(p,records,v.group);
 const missing=records.filter(r=>!values(p,r,v.group).length);
 if(v.group!=='none'&&missing.length)groups.push({label:'No grouping value recorded',recordIds:missing.map(r=>r.local_id)});
 return `<div class="table-scroll register-scroll" role="region" aria-label="Policy source records" tabindex="0"><table class="data-table evidence-table"><caption>${records.length} source records${v.group!=='none'?'; groups can overlap':''}. Open a statement to inspect evidence.</caption><thead><tr>${v.columns.map(c=>`<th scope="col">${COLUMNS[c]}</th>`).join('')}</tr></thead><tbody>${groups.map(g=>`${g.label?`<tr class="group-row"><th colspan="${v.columns.length}" scope="rowgroup">${esc(g.label)} · ${g.recordIds.length}</th></tr>`:''}${renderRows(records.filter(r=>g.recordIds.includes(r.local_id)))}`).join('')}</tbody></table></div>`;
}
export function deliveryMatrix(p,records,filters={}){const rows=records.filter(r=>r.kind==='commitment');return `<section class="visual-summary"><h3>Implementation information</h3><p class="muted">${rows.length} commitment source records. Missing information does not establish implementation failure.</p><div class="table-scroll" role="region" aria-label="Implementation information matrix" tabindex="0"><table class="data-table"><thead><tr><th>Action</th><th>Lead responsibility</th><th>Finance</th><th>Indicator</th><th>Timeframe</th></tr></thead><tbody>${rows.map(r=>`<tr><th scope="row"><button class="table-link" data-record="${esc(r.local_id)}">${esc(r.label_en)}</button></th><td>${esc(matchingDetails(r,r.actors,filters).some(a=>a.role==='lead')?'Lead stated':missingText(p,r,'/actors'))}</td><td>${esc(matchingDetails(r,r.finance,filters).length?'Finance statement recorded':missingText(p,r,'/finance'))}</td><td>${esc(matchingDetails(r,r.indicators,filters).length?'Indicator recorded':missingText(p,r,'/indicators'))}</td><td>${esc(matchingTargets(r,filters).some(t=>t.target_period)?matchingTargets(r,filters).map(t=>t.target_period).filter(Boolean).join('; '):missingText(p,r,'/targets'))}</td></tr>`).join('')}</tbody></table></div></section>`;}
export function dateTable(records,filters={}){const targets=records.flatMap(r=>matchingTargets(r,filters).map(t=>({r,t})));return `<section class="visual-summary"><h3>Stated target dates</h3><p class="muted">${targets.length} target variants from ${records.length} source records. Raw periods stay intact; passed dates do not prove failure.</p><div class="table-scroll" tabindex="0" role="region" aria-label="Stated target dates"><table class="data-table"><thead><tr><th>Period as stated</th><th>Target and condition</th></tr></thead><tbody>${targets.map(({r,t})=>`<tr><th scope="row">${esc(t.target_period||'No extracted period')}</th><td><button class="table-link" data-record="${esc(r.local_id)}">${esc(targetText(t))}</button></td></tr>`).join('')}</tbody></table></div></section>`;}
